package com.fann.asterisk;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.*;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import java.security.SecureRandom;
import java.util.concurrent.Executors;
import org.json.*;

public class MainActivity extends Activity {
 final java.util.concurrent.ExecutorService worker=Executors.newSingleThreadExecutor();
 final Handler handler=new Handler(Looper.getMainLooper());
 LinearLayout page;TextView state,detail,progress;HealthMonitor healthMonitor;JSONObject latest=new JSONObject();boolean loading=false,visible=false;
 int ink=Color.rgb(26,40,59),blue=Color.rgb(28,86,180);
 final Runnable poll=new Runnable(){public void run(){if(visible){refresh(false);if(healthMonitor!=null)healthMonitor.refresh();handler.postDelayed(this,10000);}}};
 interface Work{String run()throws Exception;}
 public void onCreate(Bundle saved){super.onCreate(saved);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);getWindow().setStatusBarColor(Color.rgb(243,246,251));getWindow().setNavigationBarColor(Color.rgb(243,246,251));getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);
  ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(Color.rgb(243,246,251));page=new LinearLayout(this);page.setOrientation(1);page.setPadding(dp(20),dp(24),dp(20),dp(32));scroll.addView(page);setContentView(scroll);
  text(page,"Asterisk 助手",28,true);text(page,"手机上的 SIP 服务器",14,false);
  LinearLayout status=card();text(status,"服务器状态",17,true);state=text(status,"正在检查 Root 与部署状态…",23,true);detail=text(status,"",14,false);progress=text(status,ManagerService.message,13,false);
  row(status,new String[]{"刷新 / Root 授权","启动"},new Runnable[]{()->refresh(true),()->service("START")});
  row(status,new String[]{"停止","重启"},new Runnable[]{()->confirm("停止服务器？","现有客户端将暂时断开。",()->service("STOP")),()->confirm("重启服务器？","现有通话会中断，请先结束通话。",()->service("RESTART"))});
  healthMonitor=new HealthMonitor(this);
  LinearLayout deploy=card();text(deploy,"部署与迁移",17,true);text(deploy,"首次部署需要 Root、Wi-Fi 和约 500 MB 空间。运行环境下载会校验完整性。",14,false);
  button(deploy,"一键部署 Asterisk",()->confirm("部署 Asterisk","将下载 Ubuntu ARM64 运行环境并安装 Asterisk。已有本 App 配置会保留；首次使用端口 16060。",()->service("DEPLOY")));
  button(deploy,"迁移现有账号与配置",()->confirm("迁移旧部署","保留现有 SIP 账号、密码、拨号配置和端口。迁移时会短暂重启服务器，旧部署在验证后再清理。",()->service("IMPORT")));
  row(deploy,new String[]{"账号与回声自检","清理旧部署"},new Runnable[]{()->service("SELFTEST"),()->confirm("删除旧部署","仅删除旧 Asterisk 服务器、旧开机脚本和“SIP 服务器后台”辅助 App。迁移及回声验证通过后才允许清理。",()->service("CLEANUP"))});
  LinearLayout manage=card();text(manage,"可视化管理",17,true);button(manage,"SIP 账号与连接方式",()->accounts());button(manage,"SIP / RTP 端口",()->ports());button(manage,"拨号规则与配置文件",()->chooseFile());button(manage,"查看运行日志",()->async(()->RootBridge.api("logs",null).optString("content"),s->showText("运行日志",s)));
  LinearLayout options=card();text(options,"后台运行",17,true);
  Switch boot=new Switch(this);boot.setText("开机自动启动");boot.setChecked(getSharedPreferences("app",0).getBoolean("autostart",true));options.addView(boot);boot.setOnCheckedChangeListener((b,on)->async(()->{RootBridge.run(RootBridge.BASE+"/control.sh autostart "+(on?"1":"0"),null,15);getSharedPreferences("app",0).edit().putBoolean("autostart",on).apply();return on?"开机自启已开启":"开机自启已关闭";},this::toast));
  Switch wake=new Switch(this);wake.setText("专用唤醒锁（增加耗电）");wake.setChecked(getSharedPreferences("app",0).getBoolean("awake",false));options.addView(wake);wake.setOnCheckedChangeListener((b,on)->{getSharedPreferences("app",0).edit().putBoolean("awake",on).apply();service("WAKE");toast(on?"已启用专用唤醒锁":"已关闭专用唤醒锁");});
  text(options,"保持通知可见，并允许后台运行。账号密码只保存在本机 Root 私有目录。卸载前请关闭自动检查，再停止服务器。",13,false);
  text(page,"Asterisk 助手 1.1.0 · ARM64 / Root\n当前预置回声号码：600",12,false);
  if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},7);
  refresh(true);healthMonitor.refresh();
 }
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 TextView text(LinearLayout box,String value,int size,boolean bold){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(ink);v.setPadding(0,dp(5),0,dp(7));if(bold)v.setTypeface(null,Typeface.BOLD);box.addView(v);return v;}
 LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(16),dp(14),dp(16),dp(14));GradientDrawable background=new GradientDrawable();background.setColor(Color.WHITE);background.setCornerRadius(dp(18));c.setBackground(background);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,-2);params.topMargin=dp(16);page.addView(c,params);return c;}
 Button button(LinearLayout box,String label,Runnable action){Button b=new Button(this);b.setText(label);b.setTextSize(14);b.setAllCaps(false);b.setTextColor(blue);b.setOnClickListener(v->action.run());box.addView(b,new LinearLayout.LayoutParams(-1,dp(52)));return b;}
 void row(LinearLayout box,String[] labels,Runnable[] actions){LinearLayout r=new LinearLayout(this);box.addView(r);for(int i=0;i<labels.length;i++){Button b=new Button(this);b.setText(labels[i]);b.setAllCaps(false);b.setTextSize(13);b.setTextColor(blue);final Runnable a=actions[i];b.setOnClickListener(v->a.run());r.addView(b,new LinearLayout.LayoutParams(0,dp(52),1));}}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 void confirm(String title,String message,Runnable yes){new AlertDialog.Builder(this).setTitle(title).setMessage(message).setNegativeButton("取消",null).setPositiveButton("继续",(d,w)->yes.run()).show();}
 void showText(String title,String value){TextView v=new TextView(this);v.setText(value);v.setTextSize(14);v.setTextIsSelectable(true);v.setPadding(dp(20),dp(12),dp(20),dp(12));ScrollView s=new ScrollView(this);s.addView(v);new AlertDialog.Builder(this).setTitle(title).setView(s).setPositiveButton("关闭",null).show();}
 interface Done{void accept(String value);}
 void async(Work work,Done done){worker.submit(()->{try{String value=work.run();runOnUiThread(()->done.accept(value));}catch(Exception e){runOnUiThread(()->toast(e.getMessage()==null?"操作失败":e.getMessage()));}});}
 void service(String action){if(ManagerService.busy&&!action.equals("WAKE")){toast("正在处理上一项操作，请稍候");return;}startForegroundService(new Intent(this,ManagerService.class).putExtra("action",action));progress.setText("已提交操作…");handler.postDelayed(()->refresh(false),1800);}
 void refresh(boolean stage){if(loading)return;loading=true;worker.submit(()->{try{if(stage)RootBridge.stage(this);JSONObject data=RootBridge.api("status",null);runOnUiThread(()->{latest=data;state.setText(data.optBoolean("installed")?(data.optBoolean("running")?"● 运行中":"○ 已停止"):"尚未部署");JSONObject p=data.optJSONObject("ports");detail.setText(data.optBoolean("installed")?data.optString("version")+"\nWi-Fi："+data.optString("ip")+"\nSIP UDP："+(p==null?"":p.optInt("lanPort"))+"  ·  通话："+data.optInt("activeCalls")+"\n"+(data.optBoolean("legacyFound")?"检测到旧部署，可迁移后清理":data.optBoolean("legacyCleaned")?"旧部署已清理":"由本 App 管理"):"需要 Root 授权后进行一键部署");String msg=ManagerService.message.equals("就绪")?getSharedPreferences("app",0).getString("message","就绪"):ManagerService.message;JSONObject deployment=data.optJSONObject("progress");if(ManagerService.busy&&deployment!=null)msg+="\n安装阶段："+deployment.optString("phase")+" "+deployment.optInt("percent")+"%";progress.setText(msg);});}catch(Exception e){runOnUiThread(()->{state.setText("等待 Root 授权 / 重试");detail.setText(e.getMessage());});}finally{loading=false;}});}
 void accounts(){async(()->RootBridge.api("accounts",null).toString(),value->{try{JSONArray a=new JSONObject(value).getJSONArray("accounts");String[] rows=new String[a.length()+1];for(int i=0;i<a.length();i++){JSONObject item=a.getJSONObject(i);rows[i]=item.getString("user")+" · "+(item.optString("role").equals("gateway")?"手机网关":"SIP 客户端")+" · "+item.optString("contactState");}rows[a.length()]="＋ 添加账号";new AlertDialog.Builder(this).setTitle("SIP 账号").setItems(rows,(d,which)->{try{if(which==a.length())editAccount(null);else accountMenu(a.getJSONObject(which));}catch(Exception e){toast("账号读取失败");}}).setNegativeButton("关闭",null).show();}catch(Exception e){toast("账号读取失败");}});}
 void accountMenu(JSONObject account){String user=account.optString("user");new AlertDialog.Builder(this).setTitle("账号 "+user).setItems(new String[]{"查看连接信息和密码","修改密码","删除账号"},(d,index)->{if(index==0)async(()->RootBridge.api("credentials",new JSONObject().put("user",user)).toString(),s->{try{JSONObject c=new JSONObject(s);JSONObject p=latest.optJSONObject("ports");boolean gateway=c.optString("role").equals("gateway");String host=gateway?"127.0.0.1":latest.optString("ip");int port=p==null?15060:p.optInt(gateway?"localPort":"lanPort");showText("连接信息（请勿分享截图）","用户名 / 认证 ID："+user+"\n密码："+c.optString("password")+"\nSIP 域名："+host+"\nSIP 代理：sip:"+host+":"+port+"\n传输：UDP\n回声测试：600");}catch(Exception e){toast("读取失败");}});else if(index==1)editAccount(account);else confirm("删除账号 "+user,"对应客户端将无法登录。",()->async(()->RootBridge.api("delete_account",new JSONObject().put("user",user)).optString("message","账号已删除"),s->{toast(s);refresh(false);}));}).setNegativeButton("返回",null).show();}
 EditText input(LinearLayout box,String label,String value,boolean password){text(box,label,14,false);EditText e=new EditText(this);e.setSingleLine(true);e.setText(value);e.setInputType(password?InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD:InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);box.addView(e,new LinearLayout.LayoutParams(-1,dp(48)));return e;}
 LinearLayout form(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(20),dp(8),dp(20),dp(12));return l;}
 String randomPassword(){byte[] bytes=new byte[16];new SecureRandom().nextBytes(bytes);StringBuilder b=new StringBuilder();for(byte v:bytes)b.append(String.format("%02x",v&255));return b.toString();}
 void editAccount(JSONObject existing){LinearLayout f=form();EditText user=input(f,"用户名",existing==null?"":existing.optString("user"),false);user.setEnabled(existing==null);EditText password=input(f,"新密码（16–64 位字母、数字、- 或 _）",existing==null?randomPassword():"",true);text(f,existing==null?"新密码已随机生成，可自行替换。":"留空保留原密码。",12,false);Spinner role=new Spinner(this);role.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"SIP 客户端（Wi-Fi）","手机网关（仅本机）"}));if(existing!=null){role.setSelection(existing.optString("role").equals("gateway")?1:0);role.setEnabled(false);}f.addView(role);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(existing==null?"添加账号":"修改账号").setView(f).setNegativeButton("取消",null).setPositiveButton("保存",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{String u=user.getText().toString(),pw=password.getText().toString();if(!u.matches("[A-Za-z0-9_-]{1,32}")||(!pw.isEmpty()&&!pw.matches("[A-Za-z0-9_-]{16,64}"))||(existing==null&&pw.isEmpty())){toast("请检查用户名或密码格式");return;}async(()->RootBridge.api("save_account",new JSONObject().put("user",u).put("password",pw).put("role",role.getSelectedItemPosition()==1?"gateway":"client")).optString("message","账号已保存"),s->{password.setText("");dialog.dismiss();toast(s);refresh(false);});}));dialog.show();}
 void ports(){JSONObject p=latest.optJSONObject("ports");if(p==null){toast("请先部署并刷新状态");return;}LinearLayout f=form();EditText lan=input(f,"Wi-Fi SIP UDP 端口",p.optInt("lanPort")+"",false),local=input(f,"本机网关 SIP UDP 端口",p.optInt("localPort")+"",false),start=input(f,"RTP 起始端口",p.optInt("rtpStart")+"",false),end=input(f,"RTP 结束端口",p.optInt("rtpEnd")+"",false);for(EditText e:new EditText[]{lan,local,start,end})e.setInputType(InputType.TYPE_CLASS_NUMBER);text(f,"保存后重启服务器，客户端需同步修改 SIP 代理端口。",12,false);new AlertDialog.Builder(this).setTitle("端口设置").setView(f).setNegativeButton("取消",null).setPositiveButton("保存并重启",(d,w)->async(()->RootBridge.api("set_ports",new JSONObject().put("lanPort",Integer.parseInt(lan.getText().toString())).put("localPort",Integer.parseInt(local.getText().toString())).put("rtpStart",Integer.parseInt(start.getText().toString())).put("rtpEnd",Integer.parseInt(end.getText().toString()))).optString("message"),s->{toast(s);service("RESTART");})).show();}
 void chooseFile(){String[] names={"extensions.conf","pjsip.conf","rtp.conf","modules.conf","logger.conf"};new AlertDialog.Builder(this).setTitle("配置文件（高级）").setItems(names,(d,w)->async(()->RootBridge.api("read_file",new JSONObject().put("file",names[w])).optString("content"),value->editFile(names[w],value))).setNegativeButton("关闭",null).show();}
 void editFile(String name,String content){LinearLayout f=form();text(f,"保存前自动保留一份备份。配置中的账号密码请保密。",12,false);EditText editor=new EditText(this);editor.setText(content);editor.setTextSize(12);editor.setTypeface(Typeface.MONOSPACE);editor.setGravity(Gravity.TOP);editor.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);ScrollView scroll=new ScrollView(this);scroll.addView(editor);f.addView(scroll,new LinearLayout.LayoutParams(-1,dp(360)));new AlertDialog.Builder(this).setTitle(name).setView(f).setNegativeButton("取消",null).setNeutralButton("恢复上次备份",(d,w)->async(()->RootBridge.api("restore_file",new JSONObject().put("file",name)).optString("message"),this::toast)).setPositiveButton("保存",(d,w)->async(()->RootBridge.api("save_file",new JSONObject().put("file",name).put("content",editor.getText().toString())).optString("message"),this::toast)).show();}
 protected void onResume(){super.onResume();visible=true;handler.postDelayed(poll,4000);}
 protected void onPause(){visible=false;handler.removeCallbacks(poll);super.onPause();}
 protected void onDestroy(){worker.shutdown();super.onDestroy();}
}
